"""Regression coverage for the behavior specified in SPEC.md."""

import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_in_denominator():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == pytest.approx(1 / 3)
    assert monitor_flag_rate([{"flagged": None}]) == 0.0


def test_monitor_flag_rate_empty():
    rate = monitor_flag_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": False}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_flag_rate_without_transcripts(groups):
    rate = pooled_flag_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts, days, expected",
    [([1, 2, 4, 8], 2, 12), ([1, 2], 0, 0), ([1, 2], 2, 3),
     ([1, 2], 10, 3), ([], 3, 0), ([], 0, 0)],
)
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = [
        "", " \t\n", "# comment", " \t# another,comment",
        " a , 2 , 1 \n", " b , -1 , 0 ", " c , 0 , \t",
    ]
    assert parse_transcript_log(iter(lines)) == [
        {"id": "a", "day": 2, "flagged": True},
        {"id": "b", "day": -1, "flagged": False},
        {"id": "c", "day": 0, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["x", "x,1", "x,1,0,extra", "x,no,1", "x,1.5,0", "x,,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["# header", "", "  \t", "ok,1,1", bad_line])


def test_parse_transcript_log_only_skipped_lines():
    assert parse_transcript_log(["", " \t", "  # comment"]) == []


def test_dedupe_transcripts_last_duplicate_id_wins_then_sorts():
    events = [
        {"id": "a", "day": 10, "flagged": True},
        {"id": "b", "day": 2, "flagged": True},
        {"id": "c", "day": 1, "flagged": None},
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 2, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[2], events[3], events[4]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_fills_gaps_and_ignores_outside_range():
    events = [
        {"day": 0, "flagged": True},
        {"day": 2, "flagged": True},
        {"day": 2, "flagged": True},
        {"day": 3, "flagged": False},
        {"day": 3, "flagged": None},
        {"day": 4, "flagged": True},
        {"day": 6, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 5) == [0, 2, 0, 1, 0]
    assert daily_flag_counts(events, 2, 4) == [2, 0, 1]
    assert daily_flag_counts(events, 2, 2) == [2]
    assert daily_flag_counts(events, 4, 2) == []
    assert daily_flag_counts([], -1, 1) == [0, 0, 0]


def test_monitor_summary_pools_rounds_and_uses_calendar_days():
    groups = {
        "a": [{"day": 1, "flagged": True}],
        "b": [{"day": 3, "flagged": None}, {"day": 5, "flagged": False}],
        "empty": [],
    }
    assert monitor_summary(groups, 3) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary(groups, 10)["recent"] == 1


def test_monitor_summary_counts_all_groups_without_deduplication():
    event = {"id": "same", "day": 2, "flagged": True}
    assert monitor_summary({"a": [event], "b": [event]}, 1) == {
        "rate": 1.0, "recent": 2, "groups": 2,
    }


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_monitor_summary_without_transcripts(groups):
    assert monitor_summary(groups, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "empty": [],
        "a": [{"flagged": True}, {"flagged": False}],
        "best": [{"flagged": True}],
        "zero": [{"flagged": False}],
    }
    assert top_flagged_groups(groups, 3) == ["best", "a", "z"]
    assert top_flagged_groups(groups, 10) == ["best", "a", "z", "zero"]
    assert top_flagged_groups(groups, 0) == []
    assert top_flagged_groups({"empty": []}, 2) == []
    assert top_flagged_groups({}, 2) == []


def test_flag_rate_by_group_sorted_with_none_for_empty_groups():
    groups = {
        "z": [{"flagged": True}, {"flagged": None}],
        "b": [],
        "a": [{"flagged": False}],
    }
    rates = flag_rate_by_group(groups)
    assert rates == {"a": 0.0, "b": None, "z": 0.5}
    assert list(rates) == ["a", "b", "z"]
    assert flag_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts, expected",
    [([], 0), ([0, 0], 0), ([-1, -2, 0], 0), ([1, 2, 3], 3),
     ([1, 0, 1, 2, 0, 3], 2), ([1, -1, 2, 3, 4], 3),
     ([1, 2, 3, 0, 1], 3)],
)
def test_longest_flag_streak(counts, expected):
    assert longest_flag_streak(counts) == expected
